#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, M, D;
    cin >> n >> k >> M >> D;

    ll ans = 0;

    for (ll p = 1; p <= D; ++p) {
        ll offset = (p - 1) * k;
        ll i = max(1LL, n / M - offset);
        ll x = n / (offset + i);

        for (ll j = max(1LL, i - 1); j <= i + 1; ++j) {
            ll value = n / (offset + j);
            if (value <= M) {
                x = max(x, value);
            }
        }

        x = min(x, M);
        ans = max(ans, p * x);
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k, M, D;
    cin >> n >> k >> M >> D;

    if (n <= 0 || M <= 0 || D <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    if (k == 0) {
        printInt128((i128)D * min(n, M));
        cout << '\n';
        return 0;
    }

    int64 limit = min(D, (n - 1) / k + 1);
    int64 p = 1;
    i128 answer = 0;

    while (p <= limit) {
        int64 denominator = 1 + (p - 1) * k;
        int64 quotient = n / denominator;
        int64 value = min(M, quotient);
        int64 last;

        if (quotient >= M) {
            last = (n / M - 1) / k + 1;
        } else {
            last = (n / quotient - 1) / k + 1;
        }

        last = min(last, limit);
        answer = max(answer, (i128)last * value);
        p = last + 1;
    }

    printInt128(answer);
    cout << '\n';
    return 0;
}

